"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["74928"],{37619(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fase_sem_definitivo_sem_data_final","status":422,"titulo":"A fase que n\xe3o publica resultado definitivo precisa declarar a data final do per\xedodo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fase_sem_definitivo_sem_data_final","requisitos":["UNI-REQ-0211"],"oQueAconteceu":["Uma fase do cronograma n\xe3o publica resultado definitivo e tamb\xe9m n\xe3o declara a data final do per\xedodo. A fase que n\xe3o publica definitivo s\xf3 conclui no fim do per\xedodo: sem a data final, a fase seguinte n\xe3o teria o fato que a libera (UNI-REQ-0211). A fase com data fixada no edital j\xe1 recusa o per\xedodo incompleto por outra causa, e a fase cuja lista de produtos foi recusada n\xe3o \xe9 conferida aqui, porque n\xe3o se sabe o que ela publica.","A confer\xeancia roda na publica\xe7\xe3o inicial e na retifica\xe7\xe3o em ato \xfanico; a grava\xe7\xe3o do cronograma n\xe3o a faz. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na lista `errors[]`. O campo \xe9 `/cronograma/fases/{i}/fim`, em que `i` \xe9 a posi\xe7\xe3o da fase no documento, e a resposta traz o c\xf3digo da fase em `identificadores`, no formato `[{\\"lista\\": \\"fases\\", \\"identificador\\": \\"<c\xf3digo da fase>\\"}]`.","A mensagem da resposta diz: \\"A fase \'*c\xf3digo da fase*\' n\xe3o publica resultado definitivo e n\xe3o declara a data final do per\xedodo. Declare a data final no cronograma; ela pode ser mudada depois por retifica\xe7\xe3o do edital.\\""],"comoResolver":["Declare a data final do per\xedodo da fase no cronograma. Se a fase publica um resultado definitivo, declare-o entre os produtos dela: a fase passa a terminar nele. O painel de conformidade mostra esta pend\xeancia antes da publica\xe7\xe3o, no item `cronograma_fase_sem_definitivo_sem_data_final`."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);